  insert into public.projects (title, slug, summary, description, category, location, status, cover_image, objectives, featured, published, is_demo) values
  ('New Sanctuary Construction', 'demo-new-sanctuary', 'Sample layout for a ground-up church construction project.', 'This is a demonstration entry that shows how a construction project will appear on the website. Once the organisation publishes a real project from the admin dashboard, its verified description, location, photographs and progress updates will replace this text.', 'construction', 'Location to be confirmed', 'ongoing', '/images/gallery/construction-rising-frame.webp', array['Example objective — complete foundation and structural frame','Example objective — enclose the building and install roofing','Example objective — finish interior and dedicate the sanctuary'], true, true, true),
  ('Sanctuary Renovation', 'demo-sanctuary-renovation', 'Sample layout for restoring an existing church building.', 'A demonstration renovation project. Real renovation projects will document the condition of the existing structure, the planned works and verified progress, all managed from the admin dashboard.', 'renovation', 'Location to be confirmed', 'planned', '/images/gallery/renovation-scaffold-arches.webp', array['Example objective — structural assessment','Example objective — roof and wall repairs','Example objective — interior refurbishment'], true, true, true),
  ('Community Outreach Programme', 'demo-community-outreach-centre', 'Sample layout for a church-led community initiative.', 'A demonstration community initiative. This is where the organisation will describe real outreach programmes run through partner congregations once details are published.', 'community', 'Location to be confirmed', 'planned', '/images/gallery/outreach-shared-meal.webp', array['Example objective — identify community needs with the local church','Example objective — launch the programme'], true, true, true),
  ('Chapel Completion', 'demo-completed-chapel', 'Sample layout for a completed project.', 'A demonstration of how a completed project and its dedication will be presented.', 'construction', 'Location to be confirmed', 'completed', '/images/gallery/interiors-timber-cross.webp', array['Example objective — dedication service'], false, true, true)
insert into public.project_images (project_id, image_url, caption, display_order)
insert into public.project_updates (project_id, title, content)
insert into public.faqs (category, question, answer, display_order) values
  ('About us', 'What is Golden Blocks Mission?', 'A nonprofit Christian organisation that builds and renovates churches and supports the Gospel, working with the Seventh-day Adventist Church in the North East Kenya Field.', 1),
  ('About us', 'What does the name “Golden Blocks” mean?', 'Gold is our finest, freely offered to God. Blocks are the material of His house.', 2),
  ('Giving', 'How can I give?', 'On the Donate page: M-Pesa, Visa or Mastercard, or bank transfer.', 3),
  ('Giving', 'Is giving online secure?', 'Yes. Cards are processed by Paystack, and each gift is confirmed by the payment provider before it is recorded.', 4),
  ('Giving', 'Can I choose what my gift supports?', 'Yes. Choose an area of work or a specific project when you give.', 5),
  ('Giving', 'Can I give every month?', 'Yes, by card. M-Pesa gifts are one-time.', 6),
  ('Giving', 'Will I receive a receipt?', 'You get a confirmation email once your payment is verified. Official receipts: to be confirmed.', 7),
  ('Getting involved', 'How else can I help besides giving money?', 'Give materials, volunteer, offer professional skills, fundraise or pray. See Get Involved.', 8),
  ('Getting involved', 'Can my church or business partner with you?', 'Yes. Send a partnership enquiry and our team will reply.', 9),
  ('Getting involved', 'How does sponsorship work?', 'Choose a programme on the Sponsorship page and send an enquiry.', 10),
  ('Projects', 'How can I follow a project’s progress?', 'Each project page has photos and progress updates.', 11),
  ('Contact', 'How do I contact the team?', 'Use the form on the Contact page.', 12);
