-- ═══════════════════════════════════════════════════════════════════════
-- Seed data. Safe to run once on a fresh project (supabase db reset runs it
-- automatically). Demo projects are flagged is_demo = true and are shown
-- with a visible "Demonstration" label; replace them from /admin.
-- ═══════════════════════════════════════════════════════════════════════

-- Organisation details start empty: the site shows clearly marked placeholders
-- until an administrator fills them in under Admin → Settings.
  'email', null, 'phone', null, 'address', null, 'office_hours', null,
  'socials', '{}'::jsonb, 'bank', null, 'mpesa_paybill', null,
  'sda_logo_url', null, 'partnership_statement', null
)) on conflict (key) do nothing;

-- Curated gallery (images ship with the site under /public/images/gallery).

-- Demonstration projects (clearly labelled on the website).
with p as (
  returning id, slug
)
select p.id, i.url, 'Illustrative image', i.ord from p join (values
  ('demo-new-sanctuary', '/images/gallery/construction-laying-blocks.webp', 0),
  ('demo-new-sanctuary', '/images/gallery/construction-blockwork.webp', 1),
  ('demo-new-sanctuary', '/images/gallery/construction-mixing-mortar.webp', 2),
  ('demo-new-sanctuary', '/images/gallery/construction-foundation.webp', 3),
  ('demo-sanctuary-renovation', '/images/gallery/renovation-scaffold-interior.webp', 0),
  ('demo-sanctuary-renovation', '/images/gallery/renovation-brick-restoration.webp', 1),
  ('demo-sanctuary-renovation', '/images/gallery/renovation-scaffold-wall.webp', 2)
) as i(slug, url, ord) on i.slug = p.slug;

select id, 'Example update', 'Project updates published from the admin dashboard will appear here as a timeline, with optional photographs.'
from public.projects where slug = 'demo-new-sanctuary';

